contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: set MinSum before and after Initialized, then assert value doesn't change after Initialized
    function run(uint beforeVal, uint afterVal) public {
        // Preconditions to avoid overflow/other issues
        // Call SetMinSum with beforeVal (should set MinSum to beforeVal since not initialized yet)
        c.SetMinSum(beforeVal);
        // read MinSum now
        uint m1 = c.MinSum();
        // initialize contract
        c.Initialized();
        // attempt to change MinSum after initialization
        c.SetMinSum(afterVal);
        // read MinSum again
        uint m2 = c.MinSum();
        // Property: after initialization, SetMinSum must not change MinSum
        assert(m2 == m1);
    }
}

