contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive contract and check that Collect's ability depends on the value passed to SetMinSum.
    // Parameters:
    // depositor - address that will deposit and attempt to collect (must be an EOA controlled externally by the verifier harness)
    // depositAmt - amount of wei to deposit
    // minVal - value passed to SetMinSum
    // collectAmt - amount to attempt to collect
    // lockTime - lock duration to allow Collect to proceed (use 0 to rely on timestamps already passed)
    function runTest(address payable depositor, uint depositAmt, uint minVal, uint collectAmt, uint lockTime) public payable {
        // Preconditions for this test to be meaningful
        require(depositAmt > 0);
        require(minVal > 0);
        require(collectAmt > 0);
        // Ensure this contract has enough balance to forward depositAmt when calling c.Put
        require(address(this).balance >= depositAmt);

        // 1) Set MinSum to the chosen minVal (on original P this sets MinSum=minVal; on mutant M it sets 0)
        c.SetMinSum(minVal);
        // 2) Set log file address (must be done before using Put because P assumes LogFile is set)
        // Use the existing Log contract at address(c) if needed; but we can set to address(c) itself
        // This call exists on P and M and only allowed before Initialized
        c.SetLogFile(address(c));
        // 3) Mark as initialized so MinSum can't be changed anymore
        c.Initialized();

        // 4) From depositor, deposit depositAmt into the contract with given lockTime
        // We simulate depositor by having this contract perform the Put on their behalf via c.Put{value: ...}
        // Because Acc is keyed by msg.sender, to produce an Acc entry for depositor we need depositor to call Put itself.
        // Since we cannot make an external EOA call here, require that depositor == address(this) so the test uses this contract as the depositor.
        require(depositor == address(this));

        // Deposit into c for this contract's Acc entry
        c.Put{value: depositAmt}(lockTime);

        // Fast-forwarding time isn't possible here; ensure lockTime = 0 so collect may be attempted immediately
        require(lockTime == 0);

        // 5) Try to Collect collectAmt; Collect will only send funds if Acc.balance >= MinSum and Acc.balance >= _am and block.timestamp>unlockTime
        // We will observe whether the Collect call results in a reduction of c.Acc(address(this)).balance via the public getter.

        // Read balance before collect
        uint balBefore = c.Acc(address(this)).balance;

        // Attempt collect (may revert internally if conditions not met; Collect does not revert on failure except inside external call)
        // Call Collect to try withdrawing collectAmt
        c.Collect(collectAmt);

        // Read balance after collect
        uint balAfter = c.Acc(address(this)).balance;

        // The distinguishing rule: on the original contract P, if balBefore >= minVal and balBefore >= collectAmt then Collect should have decreased the stored balance by collectAmt.
        // On mutant M (which sets MinSum = 0), if minVal > balBefore the original contract P would NOT allow collect, but M would possibly allow it because MinSum became 0.
        // We assert the general rule that when the originally set minimum (minVal) is <= balBefore and balBefore >= collectAmt, the post-balance equals pre-balance - collectAmt.
        // This ties behavior to the value passed to SetMinSum and is violated when SetMinSum wrongly sets MinSum to 0.

        assert(!( (balBefore >= minVal && balBefore >= collectAmt) ? (balAfter == balBefore - collectAmt) : true ));
    }

    // Allow contract to receive ETH so it can forward depositAmt
    receive() external payable {}
}

