contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // No precondition: we test behavior both before and after Initialized is called by caller.
        bool reverted;
        // Attempt to call SetMinSum; behavior should be: not reverted iff contract is not initialized.
        try c.SetMinSum(1) { reverted = false; } catch { reverted = true; }
        // We cannot read internal 'intitalized', so express the rule via the observable Initialized() action:
        // If Initialized() has been called before run, then calling SetMinSum should revert; otherwise it should succeed.
        // Since we cannot detect past Initialized() directly, we enforce the equivalent: calling Initialized() now should make SetMinSum revert afterward.
        // Call Initialized() to observe transition behavior (this call is idempotent in C).
        c.Initialized();
        bool reverted_after;
        try c.SetMinSum(2) { reverted_after = false; } catch { reverted_after = true; }
        // General rule: if SetMinSum succeeded before calling Initialized(), then it must revert after calling Initialized();
        // conversely, if it reverted before, it must still revert after (since once initialized, cannot set). This captures that only uninitialized accepts SetMinSum.
        assert(reverted == true ? reverted_after == true : reverted_after == true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: set MinSum, set LogFile to this (any address), initialize,
    // deposit exactly MinSum, advance time by relying on unlock=0, then Collect the same amount.
    // The invariant: after Collect, the contract's balance decreased by the collected amount.
    // This distinguishes the mutant that disallows MinSum==0 (which prevents this sequence when MinSum==0).
    function runTest(uint setMin, uint depositAmount) public {
        // Precondition: we choose setMin and depositAmount so depositAmount == setMin.
        require(setMin == depositAmount);

        // Set log and MinSum while not initialized.
        c.SetLogFile(address(this));
        c.SetMinSum(setMin);
        c.Initialized();

        // Ensure this contract has enough Ether to forward
        require(address(this).balance >= depositAmount);

        // Record contract balance before deposit
        uint before = address(c).balance;

        // Deposit exactly depositAmount with zero lock (so unlockTime = now)
        c.Put{value: depositAmount}(0);

        // After Put, the contract balance must have increased by depositAmount
        uint afterPut = address(c).balance;
        require(afterPut == before + depositAmount);

        // Now try to collect the same amount. Conditions in original contract allow collect when
        // acc.balance >= MinSum and block.timestamp > acc.unlockTime. Since we used lock=0,
        // unlockTime was set to block.timestamp and Collect requires block.timestamp > unlockTime,
        // so to ensure success we rely on the fact that Put via fallback or immediate call may not
        // allow collect in same block on some chains. To keep it general and simple, we call Collect
        // anyway; the distinguishing case is when setMin==0: original allows MinSum==0 so collect
        // is permitted when other conditions hold, but mutant forbids setting MinSum==0 and thus
        // this sequence cannot be executed with MinSum==0 on the mutant.

        // Attempt collect of depositAmount
        c.Collect(depositAmount);

        // Final check: contract balance must be strictly less than afterPut (collected out).
        uint finalBal = address(c).balance;
        assert(finalBal < afterPut);
    }

    // Allow this test contract to receive Ether for forwarding to c
    receive() external payable {}
}

