pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: sender address and amounts and lockTime
    function testFuzz_property(address sender, uint256 sendAmount, uint256 lockTime, uint256 collectAmount) public {
        // keep amounts in reasonable ranges but broad
        vm.assume(sender != address(0));
        sendAmount = bound(sendAmount, 0, 1 ether);
        collectAmount = bound(collectAmount, 0, 1 ether);
        lockTime = bound(lockTime, 0, 1000000);

        // Ensure sender has ETH to send
        vm.deal(sender, sendAmount + 1);

        // Sender puts value into contract (calls Put via fallback or directly)
        vm.prank(sender);
        if (sendAmount > 0) {
            c.Put{value: sendAmount}(lockTime);
        } else {
            // call fallback which calls Put(0)
            vm.prank(sender);
            (bool ok, ) = address(c).call{value: 0}("0x");
            // ok may be true
            ok; 
        }

        // Attempt a Collect by the same sender for collectAmount
        bool okCollect;
        vm.prank(sender);
        try c.Collect(collectAmount) {
            okCollect = true;
        } catch {
            okCollect = false;
        }

        // The reference contract always leaves MinSum at its initial value (0) for all inputs;
        // we assert that MinSum == 0 (this holds for the reference but the mutant that forces
        // SetMinSum to require nonzero values can have made MinSum nonzero earlier and thus
        // produce a divergent value after Collect for some inputs).
        assertTrue(c.MinSum() == 0);
    }
}
